window.docContents[127].resolve({"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Interpolation___-free-and-constrained-by-a-grammar":{"contents":"#eval Env.runIO do\n  let s ← Solver.new\n  s.setOption \"produce-interpolants\" \"true\"\n\n  let x ← s.declareConst Int \"x\"\n  let y ← s.declareConst Int \"y\"\n  smt! y = 6*x + 3 >>= s.assert\n  smt!    0 ≤ x    >>= s.assert\n  let goal ← smt! ¬ (y = 5) ∧ ¬ (y = 6)\n\n  -- interpolate freely (no grammar)\n  let some i ← s.getInterpolant goal\n    | println! \"no free interpolant\"\n  println! \"free        : {i}\"\n\n  let g ← grammar! s where\n    start : Bool := atom | atom ∧ start\n    atom  : Bool := y % k = r\n    k     : Int  := 2 | 3 | 4 | 5\n    r     : Int  := 0 | 1 | 2\n\n  -- interpolate with grammar [g]\n  let some i ← s.getInterpolant goal g\n    | println! \"no constrained interpolant\"\n  println! \"constrained : {i}\"\n\n\nfree        : (= y (ite (<= y 6) 3 y))\nconstrained : (and (= (mod y 2) 1) (= (mod y 3) 0))\n\n\n","context":"Cvc.lean -- High-Level CVC5 API\u0009Overview","header":"1.8. Interpolation: free and constrained by a grammar","id":"/Overview/#Cvc___lean----High-Level-CVC5-API--Overview--Interpolation___-free-and-constrained-by-a-grammar"}});